precision highp float;
varying vec3 vWorld;
uniform vec3 uMin, uMax;
uniform float uTime, uLoad, uSeed;
uniform int uSteps;

float hash(vec3 p){ p = fract(p * 0.3183099 + 0.1); p *= 17.0; return fract(p.x * p.y * p.z * (p.x + p.y + p.z)); }
float noise(vec3 x){
  vec3 i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(hash(i), hash(i + vec3(1,0,0)), f.x), mix(hash(i + vec3(0,1,0)), hash(i + vec3(1,1,0)), f.x), f.y),
             mix(mix(hash(i + vec3(0,0,1)), hash(i + vec3(1,0,1)), f.x), mix(hash(i + vec3(0,1,1)), hash(i + vec3(1,1,1)), f.x), f.y), f.z);
}
float fbm(vec3 p){ return 0.55 * noise(p) + 0.30 * noise(p * 2.03) + 0.15 * noise(p * 4.07); }

// Giao diem tia sang va hop gioi han
vec2 boxHit(vec3 ro, vec3 rd){
  vec3 t0 = (uMin - ro) / rd, t1 = (uMax - ro) / rd;
  vec3 lo = min(t0, t1), hi = max(t0, t1);
  return vec2(max(max(lo.x, lo.y), lo.z), min(min(hi.x, hi.y), hi.z));
}

void main(){
  vec3 ro = cameraPosition;
  vec3 rd = normalize(vWorld - ro);
  vec2 h = boxHit(ro, rd);
  float t0 = max(h.x, 0.0), t1 = h.y;
  if (t1 <= t0) discard;
  int N = uSteps;
  float dt = (t1 - t0) / float(N);
  vec3 acc = vec3(0.0);
  float alpha = 0.0;
  for (int i = 0; i < 64; i++) {
    if (i >= N) break;
    float t = t0 + dt * (float(i) + 0.5);
    vec3 p = ro + rd * t;
    vec3 q = (p - uMin) / (uMax - uMin);                 // 0..1
    // Nhieu cuon len + invert(): THREE.Fire goc lay nhieu dao nguoc de tao luoi lua
    float rise = q.y - uTime * 0.55;
    float n = fbm(vec3(q.x * 6.0, rise * 4.2, q.z * 6.0) + uSeed);
    float m = 1.0 - n;
    float narrowX = 1.0 - pow(abs(q.x * 2.0 - 1.0), 2.6);   // Thu hep ngang thanh luoi lua
    float narrowZ = 1.0 - pow(abs(q.z * 2.0 - 1.0), 2.6);
    float taper = 1.0 - smoothstep(0.02, 1.0, q.y);        // Cang cao cang nhat
    float shape = smoothstep(0.24, 0.62, m * (0.42 + 0.58 * taper)) * narrowX * narrowZ;
    float d = clamp(shape * uLoad * 2.0, 0.0, 1.0);
    if (d <= 0.002) continue;
    // Dai mau thu tuc: day tron san (xanh lam) -> giua (cam) -> ngon lua (vang sang), theo do cao chu khong theo mat do
    vec3 cBlue = vec3(0.20, 0.46, 1.00);
    vec3 cMid  = vec3(1.00, 0.50, 0.10);
    vec3 cHot  = vec3(1.00, 0.94, 0.70);
    vec3 col = mix(cBlue, cMid, smoothstep(0.02, 0.34, q.y));
    col = mix(col, cHot, smoothstep(0.34, 0.88, q.y));
    float a = d * 0.34;
    acc += col * a * (1.0 - alpha);
    alpha += a * (1.0 - alpha);
  }
  if (alpha < 0.004) discard;
  gl_FragColor = vec4(acc / max(alpha, 1e-3), alpha);
}
